package cli

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/insajin/autopus-adk/pkg/version"
)

// stickyBinaryVersion is the running auto version; tests replace it.
var stickyBinaryVersion = version.Version

// maxStickyManifestBytes bounds the one manifest read this per-prompt hook does.
const maxStickyManifestBytes = 4 << 20

var releaseVersionPattern = regexp.MustCompile(`^\d+\.\d+\.\d+$`)

// stickyStaleSurfaceAlert returns a one-paragraph alert when the installed
// Claude Code surface was generated by a different auto release than the one
// running this hook, or "" when they match or the comparison means nothing.
//
// It reads one small regular file, so it fits the per-prompt hook budget that
// a full drift regeneration (auto doctor) does not. A session started on a
// stale surface follows rules the current release has replaced, and nothing
// else tells it so until someone runs auto doctor by hand.
func stickyStaleSurfaceAlert(root string) string {
	running := strings.TrimPrefix(stickyBinaryVersion(), "v")
	if !isReleaseVersion(running) {
		return ""
	}
	generator, ok := readManifestGenerator(filepath.Join(root, ".autopus", "claude-code-manifest.json"))
	if !ok || strings.TrimPrefix(generator, "v") == running {
		return ""
	}
	shown := "an older auto"
	if generator != "" {
		shown = "auto " + generator
	}
	return fmt.Sprintf("Harness alert: the installed rules and skills were generated by %s, but this project now runs auto %s. "+
		"The installed instructions may be out of date: tell the user and suggest `auto update` before relying on them.",
		shown, running)
}

// readManifestGenerator reads the generator field without following a
// symlink or blocking on a FIFO; anything unusual reports no manifest.
func readManifestGenerator(path string) (string, bool) {
	info, err := os.Lstat(path)
	if err != nil || !info.Mode().IsRegular() || info.Size() > maxStickyManifestBytes {
		return "", false
	}
	f, err := os.Open(path)
	if err != nil {
		return "", false
	}
	defer func() { _ = f.Close() }()
	data, err := io.ReadAll(io.LimitReader(f, maxStickyManifestBytes))
	if err != nil {
		return "", false
	}
	var m struct {
		Generator string `json:"generator"`
	}
	if json.Unmarshal(data, &m) != nil {
		return "", false
	}
	return m.Generator, true
}

// isReleaseVersion reports whether v is a published X.Y.Z build. Local,
// dirty, and describe-style builds (0.51.8-3-gabc) change on every compile,
// so comparing them would alert constantly.
func isReleaseVersion(v string) bool { return releaseVersionPattern.MatchString(v) }

// joinStickyAlerts joins the non-empty alerts with a blank line.
func joinStickyAlerts(alerts ...string) string {
	kept := alerts[:0:0]
	for _, a := range alerts {
		if a != "" {
			kept = append(kept, a)
		}
	}
	return strings.Join(kept, "\n\n")
}
